// Prepare context for verifier agent
const input = $input.item.json;

// Find dev_patch result from previous steps
const devPatchResult = (input.previous_results || []).find(
  r => r.agent_slug === 'dev_patch'
);

const chatInput = [
  `[VERIFIER AGENT] Verify changes for run ${input.run_id}`,
  `Task: ${input.task_kind}`,
  input.story_id ? `Story ID: ${input.story_id}` : null,
  `Risk Profile: ${input.risk_profile}`,
  '',
  devPatchResult ? `Branch: ${devPatchResult.result?.branch || 'unknown'}` : 'No dev_patch result found',
  devPatchResult ? `Files modified: ${JSON.stringify(devPatchResult.result?.files_modified || [])}` : '',
  devPatchResult ? `Patch summary: ${devPatchResult.result?.patch_summary || 'N/A'}` : '',
  '',
  'Instructions:',
  '1. Review the changes against project rules (RPC-only, i18n, type safety)',
  '2. Verify TypeScript compilation would pass',
  '3. Verify relevant tests would pass',
  '4. Check for security issues (no PII in logs, RLS, audit journal)',
  '5. Return: { passed: boolean, issues: string[], verification_summary: string }'
].filter(Boolean).join('\n');

return {
  json: {
    chatInput,
    run_id: input.run_id,
    story_id: input.story_id,
    agent_slug: 'verifier',
    branch: devPatchResult?.result?.branch || null,
    session_id: `verifier-${input.run_id}`
  }
};

// Parse verifier agent output into structured result
const agentResult = $('Verifier Agent').item.json;
const output = agentResult.output || agentResult.text || '';

// Try to extract structured data from agent output
let passed = true;
let issues = [];

// Simple heuristic: if output contains 'fail', 'issue', 'violation' => not passed
const lowerOutput = output.toLowerCase();
if (lowerOutput.includes('fail') || lowerOutput.includes('violation') || lowerOutput.includes('not passed')) {
  passed = false;
}

// Try to parse JSON from output
try {
  const jsonMatch = output.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    if (typeof parsed.passed === 'boolean') passed = parsed.passed;
    if (Array.isArray(parsed.issues)) issues = parsed.issues;
  }
} catch (e) {
  // Not JSON, use heuristic
}

return {
  json: {
    agent_slug: 'verifier',
    passed,
    issues,
    verification_summary: output,
    verdict: passed ? 'pass' : 'fail'
  }
};
